#define BaseInten 1.0
#define XNum 10
#define YNum 10
#define TimeScale 1.0
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    float canvasWidth = iResolution.x/iResolution.y;
    vec2 p = fragCoord/iResolution.y;

    float mtime = TimeScale*iTime;

    int ix = int(floor(float(XNum)*p.x));
    int iy = int(floor(float(YNum)*p.y));

    int patternID=0;
    if(ix%2==0)
    {
        patternID+=1;
    }

    if(iy%2==0)
    {
        patternID+=1;
    }
    patternID = patternID%2;

    //---col
    int colorID = ix+iy;
    vec2 colorID2=vec2(ix,iy);
    colorID = int(6.0*rand(colorID2))+int(floor(mtime));
    vec3 col = BaseInten*mix(GetColor(colorID),GetColor(colorID+1),fract(mtime));
    //___col
    col *= (patternID==0)?10.0:1.0;
    // Output to screen
    fragColor = vec4(col,1.0);
}
